  TEventToArgsMap: $ReadOnly<
    Record<string, $ReadOnlyArray<UnsafeObject>>,
  > = $ReadOnly<Record<string, $ReadOnlyArray<UnsafeObject>>>,
> implements IEventEmitter<TEventToArgsMap>
