  } else {
    return require('../Renderer/shims/ReactNative').default.dispatchCommand(
      handle,
      command,
      args,
    );
  }
}

export function sendAccessibilityEvent(
  handle: HostInstance,
  eventType: string,
): void {
  return require('../Renderer/shims/ReactNative').default.sendAccessibilityEvent(
    handle,
    eventType,
  );
