   * A stepping function, returns 1 for any positive value of `n`.
   */
  step0(n: number): number {
    return n > 0 ? 1 : 0;
  },

  /**
   * A stepping function, returns 1 if `n` is greater than or equal to 1.
   */
  step1(n: number): number {
    return n >= 1 ? 1 : 0;
  },

