  onEndReachedThreshold: ?number,
): number {
  return onEndReachedThreshold ?? 2;
}

// windowSizeOrDefault(this.props.windowSize)
export function windowSizeOrDefault(windowSize: ?number): number {
  return windowSize ?? 21;
}

