  jsValue: IS_REDUCED_MOTION_ENABLED_IN_SYSTEM,
  uiValue: makeMutable(IS_REDUCED_MOTION_ENABLED_IN_SYSTEM),
  setEnabled(value: boolean) {
    ReducedMotionManager.jsValue = value;
    ReducedMotionManager.uiValue.value = value;
  },
};

