import { convertAnimationObjectToKeyframes } from '../animationParser';

const DEFAULT_FADE_TIME = 0.3;

export const FadeInData = {
  FadeIn: {
    name: 'FadeIn',
    style: {
      0: { opacity: 0 },
      100: { opacity: 1 },
    },
    duration: DEFAULT_FADE_TIME,
  },

  FadeInRight: {
    name: 'FadeInRight',
    style: {
      0: {
        opacity: 0,
        transform: [{ translateX: '25px' }],
      },
      100: {
        opacity: 1,
        transform: [{ translateX: '0px' }],
      },
    },
    duration: DEFAULT_FADE_TIME,
  },

  FadeInLeft: {
    name: 'FadeInLeft',
    style: {
      0: {
        opacity: 0,
        transform: [{ translateX: '-25px' }],
      },
      100: {
        opacity: 1,
        transform: [{ translateX: '0px' }],
