    style: {
      0: {
        opacity: 1,
        transform: [{ translateX: '0px' }],
      },
      100: {
        opacity: 0,
        transform: [{ translateX: '-25px' }],
      },
    },
    duration: DEFAULT_FADE_TIME,
  },

  FadeOutUp: {
    name: 'FadeOutUp',
    style: {
      0: {
        opacity: 1,
        transform: [{ translateY: '0px' }],
      },
      100: {
        opacity: 0,
        transform: [{ translateY: '-25px' }],
      },
