const setGestureState = Reanimated?.setGestureState;

function create(handlerTag: number): GestureStateManagerType {
  'worklet';
  return {
    begin: () => {
      'worklet';
      if (REANIMATED_AVAILABLE) {
        // When Reanimated is available, setGestureState should be defined
