          destinationPoint,
          ANIMATION_SOURCE.GESTURE,
          velocityY / 2
        );
      },
      [
        enablePanDownToClose,
        isInTemporaryPosition,
        animatedScrollableState,
        animatedDetentsState,
        animatedKeyboardState,
        animatedPosition,
        animateToPosition,
        context,
      ]
    );
