          method: 'handleBoundingClientRect',
          category: 'layout',
          params: {
            height,
          },
        });
      }
    },
    [animatedLayoutState]
  );
  //#endregion

  //#region effects
  useBoundingClientRect(ref, handleBoundingClientRect);
  //#endregion

  return children !== null ? (
    <Animated.View
      ref={ref}
      onLayout={handleContainerLayout}
      style={containerStyle}
    >
      {children}
    </Animated.View>
  ) : null;
}

