const BottomSheetFooterContainerComponent = ({
  footerComponent: FooterComponent,
}: BottomSheetFooterContainerProps) => {
  //#region hooks
  const { animatedLayoutState, animatedPosition, animatedKeyboardState } =
    useBottomSheetInternal();
