         * store next position
         */
        const { detents } = animatedDetentsState.get();
        const index = detents?.indexOf(targetPosition) ?? -1;
        animatedAnimationState.set(state => {
          'worklet';
          return {
            ...state,
            nextPosition: targetPosition,
            nextIndex: index,
