import React, { useEffect } from 'react';
import { Dimensions, Pressable, StyleSheet, View } from 'react-native';
import Animated, { useAnimatedStyle, useSharedValue, withSpring, withTiming } from 'react-native-reanimated';
import { TabBarProps } from '../types';

export const TabBarMatchParent: React.FC<TabBarProps> = ({
  tabs,
  currentIndex,
  onTabPress: onTabPressProp,
  tabIndicatorStyle,
}) => {
  const { width } = Dimensions.get('window');
  const tabWidth = width / tabs.length;

  const activeIndex = useSharedValue(currentIndex);

  const indicatorAnimatedStyle = useAnimatedStyle(() => {
    return {
      transform: [
        {
          translateX: withTiming(activeIndex.value * tabWidth, { duration: 200 }),
        },
      ],
      width: tabWidth,
    };
  });

  useEffect(() => {
    activeIndex.value = currentIndex;
  }, [currentIndex]);

  const onTabPress = (index: number) => {
    activeIndex.value = index;
    onTabPressProp(index);
  };

  return (
    <View style={Styles.tabBarContainer}>
      {tabs.map((tab, index) => {
        const scale = useSharedValue(1);

        const touchableAnimatedStyle = useAnimatedStyle(() => {
          return {
            transform: [{ scale: scale.value }],
          };
        });

        return (
          <Pressable
            key={index}
            style={[Styles.tabItemContainer, { width: tabWidth }]}
            onPressIn={() => (scale.value = withSpring(0.75))}
            onPressOut={() => (scale.value = withSpring(1))}
            onPress={() => onTabPress(index)}
          >
            <Animated.View style={touchableAnimatedStyle}>
              {tab.renderTabBarItem(tab.key, currentIndex === index)}
