          routeIndexToTabWidthMapSV,
          routeIndexToTabOffsetMapSV,
          routeIndexToTabContentWidthMapSV,
        }}
      >
        {children}
      </TabLayoutContext.Provider>
    );
  }
);

export const useTabLayoutContext = () => useContext(TabLayoutContext);

