          } as NativeSyntheticEvent<NativeScrollEvent>);
        }
      },
      onMomentumEnd: (event) => {
        if (_onMomentumScrollEnd) {
          runOnJS(_onMomentumScrollEnd)({
            nativeEvent: event,
