              ]}
            >
              {children}
            </Animated.View>
          )}
        </Animated.ScrollView>
      </GestureDetector>
    );
    //#endregion
  })
);

const styles = StyleSheet.create({
  contentContainer: {
    flex: 1,
  },
});

