export default function TopTabViewExampleScreenGestureHandler() {
  // const [count, setCount] = useState(0);

  // useEffect(() => {
  //   const interval = setInterval(() => {
  //     setCount((prevCount) => prevCount + 1);
  //   });

  //   return () => clearInterval(interval);
  // }, []);

  const tabs = [
    { key: 'tab1', title: 'First', component: TabScreen1 },
    { key: 'tab2', title: 'Second', component: TabScreen2 },
    { key: 'tab3', title: 'Third', component: TabScreen3 },
    { key: 'tab4', title: 'Fourth', component: TabScreen4 },
    { key: 'tab5', title: 'Fifth', component: TabScreen5 },
    { key: 'tab6', title: 'Sixth', component: TabScreen6 },
  ];

  const handlePageSelected = (index: number) => {
    logger.info('TopTabViewExampleScreenGestureHandler: onPageSelected received index:', index);
  };

  logger.info('TopTabViewExampleScreenGestureHandler rendered');

  return (
    <View style={localStyles.container}>
      {/* <Text style={localStyles.counterText}>Count: {count}</Text> */}
      <TopTabViewV2
        tabs={tabs}
        initialIndex={0}
        onTabChange={handlePageSelected} // Pass the state setter to onTabChange
        tabBarStyle={{
          backgroundColor: '#e0e0e0',
          borderBottomWidth: 0,
        }}
        tabItemStyle={{
          paddingVertical: 10,
          paddingHorizontal: 20,
        }}
        tabTextStyle={{
          fontSize: 18,
        }}
        activeTabTextStyle={{
          fontWeight: 'bold',
        }}
        indicatorStyle={{
          backgroundColor: '#007AFF',
          height: 4,
        }}
        contentContainerStyle={{
          backgroundColor: '#f9f9f9',
          justifyContent: 'center',
          alignItems: 'center',
        }}
        swipeEnabled={true}
        pageLimit={1}
      />
    </View>
  );
}

